INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`RewardText`)='78c0eded8ce3bc5e254a8958f411aa45','Так значит, в руинах поселились Заблудшие Дикотопи? Как интересно... Должно быть, они помнят что-то из своего прошлого и сознают значимость этого места. Нужно узнать об этом побольше, $N! Возможно, в этом храме таится ключ к тому, чтобы вернуть Заблудших и восстановить былое величие дренеев.',''),0 FROM `quest_offer_reward` b WHERE b.`ID`=9786 AND (MD5(b.`RewardText`)='78c0eded8ce3bc5e254a8958f411aa45') ON DUPLICATE KEY UPDATE `RewardText`=IF(VALUES(`RewardText`)<>'' AND COALESCE(`quest_offer_reward_locale`.`RewardText`,'')='',VALUES(`RewardText`),`quest_offer_reward_locale`.`RewardText`);
