INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`CompletionText`)='d74e4a1e1b54ee4c1ac58040d51679ee','Я бы хотел встроить индарий в различные части наших болидов, но для этого мне нужно большое количество необработанного индария.$B$BТы сможешь найти руду индария в раскопках Ульдамана, в Бесплодных землях.$B$BГномы уже наладили собственные поставки, так что нам важно не отставать от них.',''),0 FROM `quest_request_items` b WHERE b.`ID`=1192 AND (MD5(b.`CompletionText`)='d74e4a1e1b54ee4c1ac58040d51679ee') ON DUPLICATE KEY UPDATE `CompletionText`=IF(VALUES(`CompletionText`)<>'' AND COALESCE(`quest_request_items_locale`.`CompletionText`,'')='',VALUES(`CompletionText`),`quest_request_items_locale`.`CompletionText`);
