INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`CompletionText`)='72abfd0087fe8d746183fe4b3da7189b','Так быстро $Gвернулся:вернулась;? Надеюсь, ты $Gустроил:устроила; этим бандитам и ворам из шайки Скитальцев Пустыни настоящую гоблинскую раздачу справедливости, как я тебя просил!',''),0 FROM `quest_request_items` b WHERE b.`ID`=1690 AND (MD5(b.`CompletionText`)='72abfd0087fe8d746183fe4b3da7189b') ON DUPLICATE KEY UPDATE `CompletionText`=IF(VALUES(`CompletionText`)<>'' AND COALESCE(`quest_request_items_locale`.`CompletionText`,'')='',VALUES(`CompletionText`),`quest_request_items_locale`.`CompletionText`);
