INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`CompletionText`)='e75beb37d3d5ef16bdc366a55cd1a8e1','Как только ты завоюешь доверие Древобрюхов, я уверен — они найдут, чем смогут отблагодарить тебя. Древобрюхи не забывают своих союзников, особенно в такие тёмные времена.',''),0 FROM `quest_request_items` b WHERE b.`ID`=8461 AND (MD5(b.`CompletionText`)='e75beb37d3d5ef16bdc366a55cd1a8e1') ON DUPLICATE KEY UPDATE `CompletionText`=IF(VALUES(`CompletionText`)<>'' AND COALESCE(`quest_request_items_locale`.`CompletionText`,'')='',VALUES(`CompletionText`),`quest_request_items_locale`.`CompletionText`);
