INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`CompletionText`)='08e43c4b7115bd18f794052d1235ff12','Ты уже $Gбывал:бывала; в Застывшем оазисе? Под его водами действительно есть трещина?',''),0 FROM `quest_request_items` b WHERE b.`ID`=877 AND (MD5(b.`CompletionText`)='08e43c4b7115bd18f794052d1235ff12') ON DUPLICATE KEY UPDATE `CompletionText`=IF(VALUES(`CompletionText`)<>'' AND COALESCE(`quest_request_items_locale`.`CompletionText`,'')='',VALUES(`CompletionText`),`quest_request_items_locale`.`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`CompletionText`)='22a55b398ed3a837283a43babbc24f88','А, хочешь пополнить припасы! Понимаю... В это легко поверить, если хорошенько оглядеться по сторонам.$b$bЯ готов и в дальнейшем снабжать тебя припасами, но в обмен на них попрошу соответствующее количество рекомендательных жетонов. В таком случае ты не заслужишь признательности нашего народа, но зато получишь большие шансы выжить в грядущих битвах.',''),0 FROM `quest_request_items` b WHERE b.`ID`=8846 AND (MD5(b.`CompletionText`)='22a55b398ed3a837283a43babbc24f88') ON DUPLICATE KEY UPDATE `CompletionText`=IF(VALUES(`CompletionText`)<>'' AND COALESCE(`quest_request_items_locale`.`CompletionText`,'')='',VALUES(`CompletionText`),`quest_request_items_locale`.`CompletionText`);
